import numpy as np, statsmodels.api as sm
X=df[[f"X{i}" for i in range(1,21)]]
c=X.corr().values
for i in range(20):
    for j in range(i+1,20):
        if abs(c[i,j])>0.4: print(i+1,j+1,round(c[i,j],2))
m=sm.OLS(df.Y,sm.add_constant(df[['X1','X3']])).fit();print(m.params.round(3).to_dict(),m.rsquared)
r=m.resid
for k in X:
    print(k, round(np.corrcoef(r,df[k])[0,1],2), end='; ')
d=df.copy();d['X1sq']=d.X1**2;d['X3sq']=d.X3**2;d['X13']=d.X1*d.X3
print(sm.OLS(d.Y,sm.add_constant(d[['X1','X3','X1sq','X3sq','X13']])).fit().summary().tables[1])
